from pathlib import Path
import json,itertools,numpy as np,pandas as pd,scipy.sparse as sp
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
P=Path(__file__).parent;I=P/'HCC_marker_pair_review_v2';O=P/'HCC_compartment_paired_v2';O.mkdir(exist_ok=False)
mapping=json.loads((P/'HCC_manual_compartment_map_v1.json').read_text());md=pd.read_csv(I/'pseudobulk_rows.tsv',sep='\t',dtype={'donor':str,'cluster':str});genes=pd.read_csv(I/'pseudobulk_genes.tsv',sep='\t',index_col=0);X=sp.load_npz(I/'cluster_sample_raw_pseudobulk.npz');assert X.shape==(len(md),len(genes));assert set(md.cluster)==set(mapping['cluster_to_label']);md['compartment']=md.cluster.map(mapping['cluster_to_label']);md.to_csv(O/'reviewed_pseudobulk_rows.tsv',sep='\t',index=False);rows=[];pb=[]
for key,ix in md.groupby(['donor','library','tissue','compartment'],observed=True).indices.items():
 rows.append(dict(zip(['donor','library','tissue','compartment'],key),cells=int(md.iloc[ix].cells.sum())));pb.append(sp.csr_matrix(X[ix].sum(axis=0)))
meta=pd.DataFrame(rows);Y=sp.vstack(pb).tocsr();assert Y.sum()==X.sum();sp.save_npz(O/'compartment_sample_raw_pseudobulk.npz',Y);meta.to_csv(O/'compartment_sample_metadata.tsv',sep='\t',index=False);meta.groupby(['compartment','donor','tissue']).cells.sum().to_csv(O/'compartment_paired_cell_counts.tsv',sep='\t');summary=[];signs=np.array(list(itertools.product([-1,1],repeat=3)))
for name in ['Hepatocyte_like','Endothelial_enriched_mixed','Stromal_enriched_mixed','Myeloid_enriched_mixed']:
 sel=meta.compartment.eq(name);m=meta[sel];xx=Y[sel.to_numpy()].toarray().astype(np.float64);donors=sorted(m.donor.unique());pairs=[]
 for donor in donors:
  ix=np.flatnonzero(m.donor.to_numpy()==donor);t={m.iloc[i].tissue:i for i in ix}
  if set(t)=={'Tumor','AdjNonTumor'}:pairs.append((donor,t['Tumor'],t['AdjNonTumor']))
 if len(pairs)!=3:summary.append({'compartment':name,'status':'not_tested_missing_paired_compartment','complete_pairs':len(pairs)});continue
 cpm=xx/xx.sum(axis=1)[:,None]*1e6;log=np.log2(cpm+1);diff=np.vstack([log[it]-log[ia] for _,it,ia in pairs]);effect=diff.mean(axis=0);permuted=(signs[:,:,None]*diff[None,:,:]).mean(axis=1);p=(np.abs(permuted)>=np.abs(effect)[None,:]-1e-12*(1+np.abs(effect)[None,:])).mean(axis=0);assert np.isfinite(p).all() and p.min()>=0.25;order=np.argsort(p);q=np.empty(len(p));q[order]=np.minimum(1,np.minimum.accumulate((p[order]*len(p)/np.arange(1,len(p)+1))[::-1])[::-1]);tab=pd.DataFrame({'feature_id':genes.index.astype(str),'gene_symbol_original':genes.gene_symbol_original.astype(str).to_numpy(),'mean_paired_log2CPM_difference':effect,'mean_CPM':cpm.mean(axis=0),'positive_pairs':(diff>0).sum(axis=0),'negative_pairs':(diff<0).sum(axis=0),'exact_two_sided_sign_flip_p':p,'BH_q':q})
 for k,(donor,_,_) in enumerate(pairs):tab['paired_log2CPM_difference_donor_'+donor]=diff[k]
 tab.to_csv(O/(name+'_paired_gene_results.tsv.gz'),sep='\t',index=False);valid=~tab.gene_symbol_original.isin(['nan','NA','None','']);rank=tab[valid].mean_paired_log2CPM_difference.abs().sort_values(ascending=False).head(20).index;plot=diff[:,rank].T;fig,ax=plt.subplots(figsize=(7,8));v=max(1,abs(plot).max());im=ax.imshow(plot,aspect='auto',cmap='RdBu_r',vmin=-v,vmax=v);ax.set_xticks(range(3),[str(d) for d,_,_ in pairs]);ax.set_yticks(range(len(rank)),tab.loc[rank,'gene_symbol_original'],fontsize=8);ax.set_xlabel('Paired patient');ax.set_title(name+' | exploratory paired expression differences\nTop20 absolute mean effect; not significant genes');fig.colorbar(im,ax=ax,label='Tumor minus adjacent: log2(CPM+1)');fig.tight_layout();fig.savefig(O/(name+'_paired_gene_effects.png'),dpi=160);plt.close(fig);summary.append({'compartment':name,'complete_pairs':3,'tested_features':len(tab),'min_exact_p':float(p.min()),'BH_q_below05':int((q<.05).sum()),'status':'completed_descriptive_paired_analysis'})
r={'results':summary,'independent_donors':3,'MT_QC':'not assessable; corrected NA metadata retained','tissue_comparison':'Tumor vs paired AdjNonTumor; adjacent is not healthy','statistical_unit':'donor, never individual cells','test':'exact two-sided paired sign-flip mean statistic, 8 permutations; BH across all source features within compartment; no expression threshold added','interpretation':'Small-sample exploratory paired tissue comparison; no fibrosis-to-HCC causality or confirmed gene axis','count_conservation':True};(O/'validation.json').write_text(json.dumps(r,indent=2));print(json.dumps(r))
